-- Studio CRM contracts. Contract templates (Settings > Contracts) hold Tony's contracts, loaded
-- here from the corrected versions he approved on 17 Oct 2026 (docs/contracts/). Each job type
-- has a default contract (lists.contract_key); each quote can choose another (quotes.contract_key).
-- When a quote is accepted, a contract is made for the job: a copy of the template's wording
-- (so later edits never change it) with a fingerprint (SHA-256) of exactly what's signed.
CREATE TABLE contract_templates (
  key TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  body TEXT NOT NULL,          -- HTML from the rich editor
  updated_at TEXT NOT NULL
);
INSERT INTO contract_templates (key, name, body, updated_at) VALUES ('wedding', 'Wedding contract', '<p><strong>1. Photographer’s Responsibilities.</strong> Moments in Light (&quot;Photographer&quot;) hereby agrees to perform photographic services for Client at the Event specified above in a professional, workmanlike manner according to the prevailing standards in the industry (&quot;Services&quot;). Photographer may employ one or more assistants. Photographer is not responsible for the impact on the final product of any interference caused by guests or other vendors at the Event. Photographer will make every effort to obtain, but cannot guarantee delivery of, any specific images requested by Client because of Photographer’s lack of control over the Event, its participants, weather, and any rules or restrictions of the venue or official conducting the Event.</p><p>If Photographer is exposed to (i) unsafe conditions, or (ii) objectionable or illegal acts at the Event, Photographer reserves the right to take reasonable action to remedy such a situation, including but not limited to leaving the Event. In such event, Photographer shall not be obligated to refund any of the fees paid by Client because of such action.</p><p><strong>2. Deposit/Payment.</strong> A non-refundable deposit (that shall be applied toward the total fee for the Services and will be set out in the Payment Schedule) is due upon execution of this agreement, at which time Photographer commits to being available to Client on that date (subject to non-payment, reasonable emergencies and force majeure events, see clause 10). Remaining payments of the balance due for the Services shall be made as set out in the Payment Schedule. In the event that Client fails to remit payment as specified, Photographer shall have the right to immediately terminate this Agreement with no further obligation to refund money (including the aforementioned deposit), to attend the Event or to supply images.</p><p><strong>3. Copyright.</strong> All photographs taken by Photographer at the Event, in whatever form, are copyright protected. Photographer will allow reproduction and publishing for personal use (e.g. wall hangings at home, Facebook, blogs), but any sale or publication for profit without Photographer’s express written permission is a violation of copyright law. Photographer retains copyright in all images taken at the Event. This clause shall survive the Term.</p><p><strong>4. Term.</strong> The term of this Agreement shall commence upon the execution of this Agreement, and shall terminate upon Photographer’s delivery of the images to the Client, unless terminated earlier as provided herein.</p><p><strong>5. Event Changes.</strong> Photographer must be notified immediately of any changes in schedule or location, at least 7 days in advance of the scheduled Event date. If Client notifies Photographer by phone, a written (i.e. email) confirmation must be sent within 2 days of such notification. If the date of the Event changes, and notice is not given within the period specified above, then Photographer shall be entitled to the deposit as liquidated damages for having to reschedule the event. A new deposit will need to be paid upon booking the new date, subject to Photographer''s availability.</p><p><strong>6. Cancellation.</strong> Upon acceptance of these terms and payment of the deposit, Photographer shall commit to attending the Event on the specified date and shall make no other reservations for that date. If Client cancels the Event entirely, then Photographer shall not be required to repay any of the payments made by Client.</p><p><strong>7. Delivery Date.</strong> The edited images shall be delivered no later than 4 weeks from the date of the shoot.</p><p><strong>8. Price Protection.</strong> Photographer warrants all prices quoted for Event images are valid for a period of 6 months following the Event. Orders placed after such period are subject to Photographer’s published pricing at the time of the orders’ placement.</p><p><strong>9. Model Release.</strong> Client hereby agrees that Photographer may reproduce, publish, exhibit, and otherwise use images from the Event for instructional or marketing purposes without payment of any additional fee, provided there is no specific identification of persons or events appearing in the images.</p><p><strong>10. Force Majeure.</strong> If Photographer is unable to attend Event due to fire, flood, casualty, strike, civil disturbance, war, terrorism, Photographer’s sickness, or other acts of God beyond the parties’ control, then Photographer shall return all money paid by Client (including any deposit), and this Agreement shall immediately terminate.</p><p><strong>11. Jurisdiction.</strong> New Zealand courts shall have exclusive jurisdiction over disputes arising from this Agreement, and both parties hereto consent to the jurisdiction of such courts.</p><p><strong>12. Solicitor’s Fees.</strong> The prevailing party in any litigation or dispute involving this Agreement, or the Services performed thereunder, shall be entitled to recover reasonable solicitors’ fees, costs, and expenses arising from such litigation or dispute from the non-prevailing party.</p><p><strong>13. Assignment.</strong> This Agreement may not be assigned.</p><p><strong>14. Indemnification.</strong> Client hereby acknowledges that Photographer may be limited by the guidelines or rules of the official performing the ceremony or the venue, and agrees to hold Photographer harmless for the impact such restrictions may have on the final product.</p><p><strong>15. LIMITATION OF LIABILITY.</strong> PHOTOGRAPHER’S ENTIRE LIABILITY FOR ANY CLAIM, LOSS, DAMAGE, OR INJURY ARISING UNDER OR RELATING TO THIS AGREEMENT IS LIMITED TO THE FEES PAID BY CLIENT FOR THE SERVICES. IN NO EVENT SHALL PHOTOGRAPHER BE LIABLE FOR SPECIAL, INCIDENTAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES, EVEN IF CLIENT INFORMS PHOTOGRAPHER OF CIRCUMSTANCES THAT WOULD GIVE RISE TO SUCH DAMAGES.</p><p><strong>16. Event Meals.</strong> Client shall arrange with the caterer for meals to be provided to Photographer and 1 assistant (if applicable).</p><p><strong>17. Choice of Law.</strong> This Agreement shall be governed by the laws of New Zealand, notwithstanding its conflicts of laws provisions.</p><p><strong>18. Waiver/Miscellaneous.</strong> This Agreement represents the complete and entire agreement of the parties with respect to the subject matter herein, notwithstanding any oral or written representations to the contrary made before, during, or after its execution. Any amendments to this Agreement shall only be effective if made in writing that is executed by both parties hereto.</p><p><strong>19. Protection of Deliverables/Retention of Files.</strong> Photographer shall take all reasonable steps to protect the images that are recorded at the Event until such time as the Album/images are delivered to Client. Once the Album/images have been delivered, Photographer shall have no further obligation to preserve the images of the Event, regardless of the form of media in which they are stored.</p><p><strong>20. Promotion.</strong> I/we hereby give permission for Photographer to use my/our name/s and photographic likeness in all forms and media for advertising, trade, promotional and any other lawful purposes such as promotion and marketing.</p>', '2026-10-17T06:00:00.000Z');
INSERT INTO contract_templates (key, name, body, updated_at) VALUES ('wedding-no-ads', 'Wedding contract (no ads)', '<p><strong>1. Photographer’s Responsibilities.</strong> Moments in Light (&quot;Photographer&quot;) hereby agrees to perform photographic services for Client at the Event specified above in a professional, workmanlike manner according to the prevailing standards in the industry (&quot;Services&quot;). Photographer may employ one or more assistants. Photographer is not responsible for the impact on the final product of any interference caused by guests or other vendors at the Event. Photographer will make every effort to obtain, but cannot guarantee delivery of, any specific images requested by Client because of Photographer’s lack of control over the Event, its participants, weather, and any rules or restrictions of the venue or official conducting the Event.</p><p>If Photographer is exposed to (i) unsafe conditions, or (ii) objectionable or illegal acts at the Event, Photographer reserves the right to take reasonable action to remedy such a situation, including but not limited to leaving the Event. In such event, Photographer shall not be obligated to refund any of the fees paid by Client because of such action.</p><p><strong>2. Deposit/Payment.</strong> A non-refundable deposit (that shall be applied toward the total fee for the Services and will be set out in the Payment Schedule) is due upon execution of this agreement, at which time Photographer commits to being available to Client on that date (subject to non-payment, reasonable emergencies and force majeure events, see clause 10). Remaining payments of the balance due for the Services shall be made as set out in the Payment Schedule. In the event that Client fails to remit payment as specified, Photographer shall have the right to immediately terminate this Agreement with no further obligation to refund money (including the aforementioned deposit), to attend the Event or to supply images.</p><p><strong>3. Copyright.</strong> All photographs taken by Photographer at the Event, in whatever form, are copyright protected. Photographer will allow reproduction and publishing for personal use (e.g. wall hangings at home, Facebook, blogs), but any sale or publication for profit without Photographer’s express written permission is a violation of copyright law. Photographer retains copyright in all images taken at the Event. This clause shall survive the Term.</p><p><strong>4. Term.</strong> The term of this Agreement shall commence upon the execution of this Agreement, and shall terminate upon Photographer’s delivery of the images to the Client, unless terminated earlier as provided herein.</p><p><strong>5. Event Changes.</strong> Photographer must be notified immediately of any changes in schedule or location, at least 7 days in advance of the scheduled Event date. If Client notifies Photographer by phone, a written (i.e. email) confirmation must be sent within 2 days of such notification. If the date of the Event changes, and notice is not given within the period specified above, then Photographer shall be entitled to the deposit as liquidated damages for having to reschedule the event. A new deposit will need to be paid upon booking the new date, subject to Photographer''s availability.</p><p><strong>6. Cancellation.</strong> Upon acceptance of these terms and payment of the deposit, Photographer shall commit to attending the Event on the specified date and shall make no other reservations for that date. If Client cancels the Event entirely, then Photographer shall not be required to repay any of the payments made by Client.</p><p><strong>7. Delivery Date.</strong> The edited images shall be delivered no later than 4 weeks from the date of the shoot.</p><p><strong>8. Price Protection.</strong> Photographer warrants all prices quoted for Event images are valid for a period of 6 months following the Event. Orders placed after such period are subject to Photographer’s published pricing at the time of the orders’ placement.</p><p><strong>9. Model Release.</strong> Client hereby agrees that Photographer may reproduce, publish, exhibit, and otherwise use images from the Event for instructional or marketing purposes without payment of any additional fee, provided there is no specific identification of persons or events appearing in the images.</p><p><strong>10. Force Majeure.</strong> If Photographer is unable to attend Event due to fire, flood, casualty, strike, civil disturbance, war, terrorism, Photographer’s sickness, or other acts of God beyond the parties’ control, then Photographer shall return all money paid by Client (including any deposit), and this Agreement shall immediately terminate.</p><p><strong>11. Jurisdiction.</strong> New Zealand courts shall have exclusive jurisdiction over disputes arising from this Agreement, and both parties hereto consent to the jurisdiction of such courts.</p><p><strong>12. Solicitor’s Fees.</strong> The prevailing party in any litigation or dispute involving this Agreement, or the Services performed thereunder, shall be entitled to recover reasonable solicitors’ fees, costs, and expenses arising from such litigation or dispute from the non-prevailing party.</p><p><strong>13. Assignment.</strong> This Agreement may not be assigned.</p><p><strong>14. Indemnification.</strong> Client hereby acknowledges that Photographer may be limited by the guidelines or rules of the official performing the ceremony or the venue, and agrees to hold Photographer harmless for the impact such restrictions may have on the final product.</p><p><strong>15. LIMITATION OF LIABILITY.</strong> PHOTOGRAPHER’S ENTIRE LIABILITY FOR ANY CLAIM, LOSS, DAMAGE, OR INJURY ARISING UNDER OR RELATING TO THIS AGREEMENT IS LIMITED TO THE FEES PAID BY CLIENT FOR THE SERVICES. IN NO EVENT SHALL PHOTOGRAPHER BE LIABLE FOR SPECIAL, INCIDENTAL, CONSEQUENTIAL, OR PUNITIVE DAMAGES, EVEN IF CLIENT INFORMS PHOTOGRAPHER OF CIRCUMSTANCES THAT WOULD GIVE RISE TO SUCH DAMAGES.</p><p><strong>16. Event Meals.</strong> Client shall arrange with the caterer for meals to be provided to Photographer and 1 assistant (if applicable).</p><p><strong>17. Choice of Law.</strong> This Agreement shall be governed by the laws of New Zealand, notwithstanding its conflicts of laws provisions.</p><p><strong>18. Waiver/Miscellaneous.</strong> This Agreement represents the complete and entire agreement of the parties with respect to the subject matter herein, notwithstanding any oral or written representations to the contrary made before, during, or after its execution. Any amendments to this Agreement shall only be effective if made in writing that is executed by both parties hereto.</p><p><strong>19. Protection of Deliverables/Retention of Files.</strong> Photographer shall take all reasonable steps to protect the images that are recorded at the Event until such time as the Album/images are delivered to Client. Once the Album/images have been delivered, Photographer shall have no further obligation to preserve the images of the Event, regardless of the form of media in which they are stored.</p><p><strong>20. Promotion.</strong> I/we hereby give permission for Photographer to use my/our name/s and photographic likeness on Photographer’s wedding gallery web page on the understanding that children will not be shown.</p>', '2026-10-17T06:00:00.000Z');
INSERT INTO contract_templates (key, name, body, updated_at) VALUES ('nzipp', 'NZIPP terms', '<p>NZIPP Standard Photographic Terms &amp; Conditions of Engagement</p><h3>1 INSTRUCTIONS MUST BE IN WRITING</h3><p>1.1 The Client must ensure that all instructions and expectations regarding the Booking/Order (and any subsequent variations) are agreed in writing.</p><h3>2 LICENCE GRANTED TO CLIENT</h3><p>2.1 Except as may be expressly provided in the Agreement, the copyright in all Photographic Works resulting from the Booking/Order remains the property of the Photographer. The Photographer does not accept commissions to create Photographic Works. These terms override section 21 (3) of the Copyright Act 1994.</p><p>2.2 The Photographer grants the Client a non–exclusive Licence to use those parts of the Photographic Works selected by the Photographer and presented to the Client. The Licence includes the right (if any) to reproduce and publish the Photographic Works for the purposes, territories and time periods specified in the Booking/Order, subject to these terms and conditions. The Client shall have the right to seek further Licences for use or reuse of any Photographic Works, which shall not be unreasonably refused by the Photographer but is subject to agreement of a reasonable fee for that Licence.</p><p>2.3 If the Photographic Works have been produced for an Advertiser named in the Agreement, the Photographic Works may only be used by the Advertiser. The Client must ensure that the Advertiser complies with the Client’s obligations and all other terms and conditions of the Agreement.</p><p>2.4 The Client acknowledges that the Photographer always retains the right to use the Photographic Works in any manner at any time and in any part of the world for the purposes of:</p><p>a Entering the Photographic Works into photographic competitions or awards and for their use in any material published in connection with promoting those competitions or awards; and</p><p>b Advertising or otherwise promoting the Photographer’s Work, including through the use of social media; and</p><p>c Submitting the Photographic Works for display in art galleries or other premises; and</p><p>d Using the Photographic Works for any other purpose within the Photographer’s business activities.</p><h3>3 CONDITIONS OF LICENCE</h3><p>3.1 This Licence to use, and the right to use the Photographic Works commences from the date of full payment of all amounts owed to the Photographer in relation to the Photographic Works and the Agreement, except where the Photographer gives express written permission.</p><p>3.2 This Licence must not be assigned to any third party without the Photographer’s prior written permission (which shall not be unreasonably refused), but may be sublicensed by the Client to the Advertiser named in the Agreement (if any) on the same terms and conditions of this Licence (excluding any further right to sublicense).</p><p>3.3 The Client is entitled to:</p><p>a Manipulate, distort or make other alterations to the Photographic Works (including overprinting by text or other Photographic Works), unless this right is expressly excluded in the Agreement; and</p><p>b Use only a portion of the Photographic Works.</p><p>3.4 Copyright in any new Photographic Works created from any manipulation, alteration, distortion or overprinting of text of the licensed Photographic Works shall remain with the Photographer and shall be licensed to the Client on the same terms and conditions of the Agreement.</p><p>3.5 Any breach of the Agreement by the Client (or by the Advertiser, with the Client’s knowledge) which results in damage to the professional reputation of the Photographer, entitles the Photographer to compensation from the Client for that damage in addition to any other remedies available to the Photographer.</p><h3>4 ASSIGNMENT OF COPYRIGHT</h3><p>4.1 Where the Agreement specifies that copyright in the Photographic Works is assigned to the Client in consideration for the Client’s payment for those Works:</p><p>a The Photographer assigns to the Client copyright in the Photographic Works from the date of full payment of all amounts owed to the Photographer in relation to the Photographic Works and the Agreement;</p><p>b It is the responsibility of the Client to obtain all model releases, moral right waivers and privacy waivers necessary for the use of the Photographic Works;</p><p>c The Client agrees to indemnify the Photographer in respect of any loss, claims, damages or expenses (including costs incurred on a solicitor client basis) incurred by the Photographer arising from any use of the Photographic Works; and</p><p>d The Photographer retains the rights described in clause 2.4 and clause 5 of these terms and conditions.</p><h3>5 MORAL RIGHTS</h3><p>5.1 The Photographer asserts moral rights, including attribution rights, in respect of the Photographic Works (unless expressly waived in the Agreement in writing). Each use of any Photographic Work by the Client, including where the Client publishes or otherwise uses the Photographic Works on social media, must be accompanied by an adjacent credit line acknowledging the Photographer’s name and copyright in the Photographic Works in the form specified in the Agreement, or if not so specified, then in a form approved in writing by the Photographer.</p><p>5.2 If the Client fails (for whatever reason) to provide the attribution described in clause 5.1, then in addition to all other rights under the Agreement or at law, the Client shall be liable to pay a non-attribution fee calculated at 200% of the Photographer’s fee, which the Client acknowledges and agrees to be a fair and reasonable pre-estimate of the loss suffered by the Photographer.</p><h3>6 DATA PRESERVATION</h3><p>6.1 The Client’s right to use the Photographic Works under the Licence does not include the right to remove, alter or otherwise affect any rights information accompanying or relating to the Photographic Works, including (without limitation) any notices or metadata accompanying or part of the Photographic Works recording creator details, copyright ownership or publication status of the Photographic Works. The Client shall not alter or remove any notices attached to the Photographic Works and shall take all reasonable steps to respect and preserve the Photographer’s copyright and other rights. Where the Photographer has placed restrictions on access to or use of the Photographic Works, the Client shall not defeat (or attempt to defeat) such restrictions.</p><h3>7 STORAGE AND BACKUPS</h3><p>7.1 The Client acknowledges that the Client is responsible for the storage and backup of the Photographic Works supplied by the Photographer. While the Photographer will follow its usual backup procedures (if any) upon delivery of the Photographic Works, the Photographer shall not be liable under any circumstances if unable to produce backups or future reproductions of the Photographic Works upon the request of the Client. Where backups are available, these may be made available to the Client for a fee.</p><h3>8 PRIVACY AND PERSONAL INFORMATION</h3><p>8.1 As part of creating the Photographic Works, the Photographer may collect and retain personal information about the Client. The personal information may be used by the Photographer for communicating with the Client for any purpose relating to the Photographic Works (including arranging third party services), direct marketing and in connection with these terms and conditions.</p><p>8.2 The Client authorizes the Photographer to collect, retain, use personal information for these purposes (including assessing credit worthiness), and to disclose that information to any person or entity for these purposes.</p><p>8.3 Personal information collected by the Photographer shall be retained in the Photographer’s database. The Client may access and request correction of any of the Client’s personal information by contacting the Photographer.</p><p>8.4 Where section 105 of the Copyright Act 1994 applies, the Photographer shall obtain any necessary consent in accordance with section 107 of that Act, provided however that the Client agrees that the Photographer has the rights described in clause 2.4 unless those rights are expressly excluded in the Booking/Order.</p><h3>9 PAYMENT</h3><p>9.1 The Client shall pay the Photographer the various amounts payable in accordance with the Booking/Order and the Agreement. If the Photographer’s fee and expenses are not estimated in advance, or for any goods or services different or additional to the Booking/Order, then the Client shall pay the amount invoiced by the Photographer in accordance with the Photographer’s Price List. The Photographer may require a deposit or payment of part or all of the amounts due in advance. Unless otherwise specified in the Agreement, payment of all other amounts are due within 7 days of invoice.</p><h3>10 JOB-RELATED COSTS</h3><p>10.1 The Client shall reimburse the Photographer for all Job-Related Costs. Where the Photographer makes payment to others on behalf of the Client, the Photographer may add a service charge or commission, determined at the Photographer’s absolute discretion. Unless otherwise specified in the Agreement, the Client must pay all Job-Related Costs and service charges/commissions to the Photographer within 7 days of invoice. The Client is not entitled to any property in:</p><p>a Any artistic works or other materials created or supplied by the Photographer to support the Photographic Works; or</p><p>b Any materials used for the creation of an artistic work, which are commissioned or arranged by the Photographer; or</p><p>c Any goods used in supporting the Photographic Works</p><p>10.2 Such goods, materials, authored or artistic works shall remain the property of the Photographer, unless otherwise specified in the Agreement.</p><h3>11 URGENT WORK</h3><p>11.1 Where the Client requires Photographic Works on an urgent basis (which includes where the Photographer is unable to re-shoot or correct a shot because of an urgent deadline) the Photographer will not be liable for any losses or damages arising out of the inability to carry out a re-shoot or the costs of arranging a re-shoot.</p><h3>12 CHANGES TO THE ESTIMATE</h3><p>12.1 Estimates of fees and Job-Related Costs are estimates and not firm quotations and are liable to alteration. The Photographer must bring any increase to the estimate, of 10% or more, to the attention of the Client. Any change to the job specifications made or agreed by the Client may alter the fees and Job-Related Costs.</p><h3>13 OVERDUE PAYMENTS</h3><p>13.1 In the event that any monies are not paid in full on the due date, the Photographer shall be entitled to:</p><p>a Charge interest at a rate of 2.5% per month or part month overdue on any amounts outstanding;</p><p>b Recover any debt collection costs and related legal expenses (on a solicitor-client basis); and</p><p>c Suspend any further work until all amounts owing and any costs incurred are paid in full.</p><h3>14 CANCELLATION</h3><p>14.1 When a Booking/Order is confirmed by the Client, the Client becomes liable for payment to the Photographer and the Photographer becomes liable to complete the shoot.</p><p>14.2 Cancellation of the Booking/Order by the Client must be in writing and must give reasonable notice to the Photographer. Subject to any specific terms in the Agreement, if the Client cancels the Booking/Order:</p><p>a Within 1 working day of the booked shoot day, the Client must pay a fee of 100% of the Photographer’s fees</p><p>b Giving notice of cancellation of greater than 1 working day and within 3 working days of the booked shoot day, the Client must pay a fee of 50% of the Photographer’s fees.</p><p>c Giving notice of cancellation of greater than 3 working days and within 1 week of the booked shoot day, the Client must pay a fee of 25% of the Photographer’s fees.</p><p>d The Client must pay the Photographer for all Job-Related Costs incurred.</p><p>14.3 The Client acknowledges and agrees that these cancellation fees fairly reflect the loss suffered by the Photographer and the Photographer’s ability to re-schedule work and re-allocate resources, depending upon the amount of notice given.</p><h3>15 POSTPONEMENT</h3><p>15.1 Subject to any specific terms in the Agreement, if the Client postpones or changes the date of the Booking/Order, the following shall apply:</p><p>a Within 1 working day of the booked shoot day, the Client must pay a fee of 50% of the Photographer’s daily fee for each day which is postponed.</p><p>b With more than 1 working days’ notice, the Client must pay a fee of 25% of the Photographer’s daily fee for each day which is postponed.</p><p>c The Client must pay the Photographer for all Job-Related Costs incurred.</p><p>15.2</p><p>The Client acknowledges and agrees that these cancellation fees fairly reflect the loss suffered by the Photographer and the Photographer’s ability to re-schedule work and re-allocate resources, depending upon the amount of notice given.</p><h3>16 WEATHER CONDITIONS</h3><p>16.1 A weather-permitting booking must be agreed between the Client and Photographer prior to the shoot. Upon postponement or cancellation of a shoot due to bad weather the Client must pay the Photographer all Job-Related Costs incurred up until the time that the shoot was postponed and 50% of the Photographer’s fee which was to be charged for the shoot. The Client is responsible for taking out weather insurance.</p><h3>17 WORK SUSPENDED ON CLIENT’S INSTRUCTIONS</h3><p>17.1 Where the Client instructs that work is to be suspended for a period of 30 days or more, the Client must, at the time of suspension, pay the Photographer for all work in progress and any Job-Related Costs incurred at that time.</p><h3>18 RESPONSIBILITY FOR CONTRACTORS</h3><p>18.1 The Client is responsible for making all payments (including rollover fees) and fulfilling all other obligations to contractors.</p><p>18.2 Where contractors are models, the Client is responsible for obtaining all necessary model releases. To ensure proper recording of others’ intellectual property rights, which may be part of the Photographic Works, the Client shall, on a request by the Photographer, provide evidence of these model releases to the Photographer.</p><p>18.3 Where the Client requests the Photographer to engage contractors, the Photographer shall do so as agent for the Client and the Client indemnifies the Photographer against all costs, disbursements and other obligations arising from that agency.</p><h3>19 CLIENT PROPERTY AND MATERIALS</h3><p>19.1 Client property and all property and material supplied to the Photographer by or on behalf of the Client is held at the Client’s risk and the Photographer accepts no responsibility for the maintenance or insurance of that property or material.</p><p>19.2 The Client must pay any sum charged or incurred by the Photographer for handling or storing property or material supplied by or on behalf of the Client.</p><p>19.3 Where property and materials are left with the Photographer without specific instructions, the Photographer may dispose of them at the end of six months from the date of receiving them and retain the proceeds.</p><h3>20 CLIENT CONFIDENTIALITY</h3><p>20.1 The Client must advise the Photographer as to whether any material or information supplied is of a confidential nature. The Photographer will keep that material or information confidential, except where disclosure is reasonably necessary to enable the Photographer to perform the Agreement.</p><h3>21 INDEMNITY</h3><p>21.1 The Client undertakes to indemnify the Photographer for any loss, claim, damage, or expense (including costs incurred on a solicitor client basis) suffered or incurred as a result of:</p><p>a Any breach by the Client of the Agreement;</p><p>b Any illegal or defamatory Photographic Works produced for the Client;</p><p>c Any infringement of an intellectual property right of any person; or</p><p>d In recovering any moneys due.</p><p>21.2 Such loss, claim, damage or expense shall be moneys due for the purposes of these terms and conditions.</p><p>21.3 The Client is responsible for obtaining any authorisation, clearance, licence or other form of approval necessary for the lawful use of third party intellectual property works.</p><h3>22 COLOUR VARIATION</h3><p>22.1 The Client releases the Photographer from any and all liability relating to colour reproduction of supplied works on any system not under the direct control of the Photographer. Where the Photographer supplies the Client with photographic prints, the Client acknowledges that Photographic Works may fade or discolour over time due to the inherent qualities of materials used, and releases the Photographer from any liability for any claim based upon fading or discolouration. Where a colour is unable to be reproduced accurately due to limitations in capture and output technology, the Client releases the Photographer from any and all liability in regard to colour reproduction.</p><h3>23 QUALITY OF PHOTOGRAPHIC WORKS</h3><p>23.1 Where Photographic Works are not of an acceptable technical quality, making it unfit for the purpose of its specified use, then no fee or Job-Related Costs are due to the Photographer. The Photographer has the right to rectify the defect within a reasonable time, having regard to the urgency of the work. If rectified, the Photographer is entitled to be paid the full fee and Job-Related Costs, but may not charge the Client any extra fee or cost for rectifying the defect.</p><p>23.2 Where there is a representative of the Client at the shoot, the representative is responsible for the direction of the work. Acceptance of the work by this representative is confirmation that the Photographer has satisfied the artistic quality and interpretation requirements of the shoot. If the representative is not at the shoot then the Photographer’s judgement is absolute within the limits (if any) imposed by any documented agreements on the nature of the intended work.</p><p>23.3 If the Photographer produces Photographic Works that are in the same style and structure as the Photographer’s past work (by reference to the Photographer’s portfolio), the Client is deemed to have accepted the Photographer’s artistic interpretation.</p><p>23.4 If there is a dispute as to artistic interpretation, which is unresolved after good faith discussions between the Photographer and the Client, and where the Photographer is a member of a recognised photographic association or society, the chief executive (or equivalent) of that association or society shall determine the dispute. That decision shall be final and binding.</p><h3>24 CONSUMER GUARANTEES ACT 1993</h3><p>24.1 The Consumer Guarantees Act 1993 may apply to the Photographic Works provided by the Photographer, if the Client acquires those Photographic Works for personal, domestic or household use or consumption. If this Act applies, nothing in the Agreement will limit or exclude the Client’s rights under this Act.</p><p>24.2 If the Client is acquiring the Photographic Works for business or trade purposes, then the Client’s rights are subject to the Agreement only and the Consumer Guarantees Act 1993 shall not apply.</p><h3>25 PHOTOGRAPHER NOT LIABLE FOR LOSSES</h3><p>25.1 Except as provided by the Consumer Guarantees Act 1993, the Photographer shall not be liable for:</p><p>a Any loss or damage arising by reason of any delay in the completion of the Photographic Works; or</p><p>b Any loss of profits or revenues; or</p><p>c Any indirect or consequential loss of whatever nature; or</p><p>d Any loss resulting from any errors or omissions arising from an oversight or a misinterpretation of a Client’s verbal instructions.</p><h3>26 LIABILITY OF PHOTOGRAPHER LIMITED</h3><p>26.1 Subject to clause 24, the Photographer’s liability to the Client for any and all costs, loss or damage suffered by the Client, however caused (including negligence), arising out of or connected with the performance or failure of performance of any Photographic Works or photographic services supplied by the Photographer, shall not exceed the full value of the payments made by the Client under the Agreement.</p><h3>27 HEALTH AND SAFETY</h3><p>27.1 The Client acknowledges and agrees that the Client is responsible for, and shall take all reasonably necessary steps to ensure, its own personal safety and that no action or inaction of the Client causes harm or risk to the health and safety of others. Notwithstanding the above, the Client agrees to comply with any reasonable health and safety directions given by the Photographer.</p><h3>28 FORCE MAJEURE</h3><p>28.1 Except for an obligation to pay money, neither the Client nor the Photographer shall be liable for any act, omission or failure to fulfil its obligations, or any loss or damage arising directly or indirectly due to an act of God, explosion, fire, flood, storm, earthquake, subsidence, armed conflict, strike, lockout or labour disputes, civil commotion, intervention of a government, accidents, electrical, heat, light or telecommunication failures, interruption to transportation, weather or any other cause outside the Photographer’s control.</p><h3>29 DISPUTE RESOLUTION</h3><p>29.1 The Photographer and the Client agree to use their best efforts to resolve any dispute which arises through good faith negotiations.</p><p>29.2 Either party may raise a dispute by written notice to the other party. Within 3 working days of receipt of a dispute notice, the parties shall meet (or otherwise communicate if meeting is not practicable) and attempt to resolve the dispute through good faith negotiations on a ‘without prejudice’ basis.</p><p>29.3 Neither party may commence any litigation in relation to the dispute unless 14 days have passed since the parties met (or otherwise communicated) and endeavoured in good faith to resolve the dispute on mutually acceptable terms.</p><h3>30 CONFLICTS</h3><p>30.1 In the event of a conflict or inconsistency between these terms and conditions and the Booking/Order, the Booking/Order shall prevail.</p><h3>31 GOVERNING LAW</h3><p>31.1 These terms and conditions are governed by, and to be construed in accordance with New Zealand Law. The Client irrevocably submits to the exclusive jurisdiction of the New Zealand courts.</p><h3>32 ENTIRE AGREEMENT</h3><p>32.1 The Booking/Order, together with these standard terms and conditions and any other special conditions agreed in writing between the parties, shall constitute the entire Agreement between the parties.</p><p>32.2 Each Booking/Order made by the Client shall (together with these standard terms and conditions and any other special conditions agreed in writing between the parties) constitute a separate Agreement between the parties.</p><h3>DEFINITIONS</h3><p>For the purposes of the Agreement, the following definitions shall apply unless the context requires otherwise:</p><p>Advertiser: means the end user of the Photographic Works where the Photographer is engaged to produce the Photographic Works by an advertising agency, design firm, or other intermediary.</p><p>Agreement: means the Booking/Order, together with these standard terms and conditions and any other special conditions agreed in writing between the parties.</p><p>Booking/Order: means an order or request by the Client for the production, supply or viewing of Photographic Works, including (without limitation) bookings, orders, quotes, estimates, proposals, and appointments made for a shoot, sitting or viewing.</p><p>Client: means the person or entity listed on the Booking/Order who engages or instructs the Photographer to produce Photographic Works.</p><p>Job-Related Costs: means any costs and expenses incurred by the Photographer on the Client’s behalf in providing photographic services or in the creation of the Photographic Works.</p><p>Licence: is a right granted by the Photographer to the Client to use the copyright works of the Photographer on the terms set out above.</p><p>Photographic Works: means the deliverable works specified in the Booking/Order and created or supplied by the Photographer, including photographs, photographic prints, moving images (video), transparencies, negatives, digital files, and images in any form or medium.</p><p>Photographer: means the photographer and where the context requires may include, the studio, photographic company, employees or sub-contractors.</p><p>Price List: means the Photographer’s list or schedule of prices for goods and services at the date of the Agreement.</p><p>© 2019 AIPA / NZIPP / Clendons</p><p>Advertising &amp; Illustrative Photographers Association | <a href="http://www.aipa.org.nz/">www.aipa.org.nz</a></p><p>New Zealand Institute of Professional Photography | <a href="http://www.nzipp.org.nz/">www.nzipp.org.nz</a></p><p>Standard Photographic Terms &amp; Conditions of Engagement</p>', '2026-10-17T06:00:00.000Z');

ALTER TABLE lists ADD COLUMN contract_key TEXT;
UPDATE lists SET contract_key = 'wedding' WHERE kind = 'job_type' AND value = 'Wedding';
ALTER TABLE quotes ADD COLUMN contract_key TEXT;

-- status: sent | signed | void
CREATE TABLE contracts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  job_id INTEGER NOT NULL REFERENCES jobs (id),
  quote_id INTEGER REFERENCES quotes (id),
  token TEXT NOT NULL UNIQUE,
  template_key TEXT,
  name TEXT NOT NULL,
  details TEXT NOT NULL DEFAULT '{}',  -- the event details shown above the wording (JSON)
  body TEXT NOT NULL,                  -- the wording, as sent
  fingerprint TEXT NOT NULL,           -- SHA-256 of details + body
  status TEXT NOT NULL DEFAULT 'sent',
  sent_at TEXT,
  viewed_at TEXT,
  signed_name TEXT,
  signed_at TEXT,
  signed_ip TEXT,
  signed_agent TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX contracts_job ON contracts (job_id);
